type BenchProvenance = {
  source?: string;
  timestamp?: string | null;
  gitSha?: string | null;
  os?: string | null;
  node?: string | null;
  model?: string | null;
};

/**
 * Provenance for every number on this page: each row is regenerated by
 * `npm run sync:benchmarks` from the checked-in result JSONs in the repo,
 * so the table updates whenever a benchmark script re-runs.
 */
function VerifiedRuns() {
  const benchRows: Array<[string, BenchProvenance]> = [
    ["LoCoMo · full dataset", benchmarksData.locomo],
    ["LongMemEval-S", benchmarksData.longmemeval],
    ["BEAM-1M", benchmarksData.beam],
    ["Memory haystack", benchmarksData.haystack],
    ["HotPotQA", benchmarksData.hotpot],
    ["ConvoMem", benchmarksData.convomem],
    ["LoCoMo span aggregation", benchmarksData.spans],
    ["QA arms", benchmarksData.qaArms],
  ];
  const rows = benchRows
    .filter(([, data]) => data?.timestamp)
    .map(([name, data]) => ({ name, data }));

  if (rows.length === 0) return null;

  return (
    <Reveal className="mb-12">
      <h2 className="section-title">Verified runs</h2>
      <div className="card overflow-x-auto">
        <table className="data-table">
          <thead>
            <tr>
              <th>Benchmark</th>
              <th>Run date</th>
              <th>Commit</th>
              <th>Embedding model</th>
              <th>Environment</th>
            </tr>
          </thead>
          <tbody>
            {rows.map(({ name, data }) => (
              <tr key={name}>
                <td>
                  {name}
                  <div className="font-mono text-[10px] text-zinc-600 mt-0.5">
                    {data.source}
                  </div>
                </td>
                <td className="whitespace-nowrap tabular-nums text-[11px] text-zinc-300">
                  {data.timestamp ? data.timestamp.slice(0, 10) : "—"}
                </td>
                <td className="whitespace-nowrap font-mono text-xs text-zinc-400">
                  {data.gitSha ? data.gitSha.slice(0, 7) : "—"}
                </td>
                <td className="text-xs text-zinc-400">{data.model || "—"}</td>
                <td className="text-xs text-zinc-500">
                  {data.os || "—"} · {data.node || "—"}
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
      <p className="mt-4 text-xs text-zinc-600 leading-relaxed">
        Regenerated automatically from result JSONs committed to the repo —
        if a number on this page can&apos;t be traced to a run below, treat it
        as marketing.
      </p>
    </Reveal>
  );
}

